-- DOCUMENTATION ONLY. PostgreSQL 16. Never execute from this project.
-- ids are generated by the application (no DB defaults).

-- Platform-level, append-only. Never contains patient data.
CREATE TABLE platform_audit_log (
  id            uuid PRIMARY KEY,
  actor_user_id uuid NOT NULL,
  action        text NOT NULL,
  clinic_id     uuid NULL REFERENCES clinics (id),
  details       jsonb NOT NULL,
  created_at    timestamptz NOT NULL
);
CREATE INDEX platform_audit_log_created_idx ON platform_audit_log (created_at DESC);
CREATE INDEX platform_audit_log_clinic_idx ON platform_audit_log (clinic_id, created_at DESC);
